52	import org.springframework.security.access.prepost.PreAuthorize;
53	import org.springframework.web.bind.annotation.CrossOrigin;
54	import org.springframework.web.bind.annotation.RequestMapping;
55	import org.springframework.web.bind.annotation.RestController;
56	import org.springframework.web.util.UriComponentsBuilder;
57	
58	import jakarta.transaction.Transactional;
59	
60	/**
61	 * @author Vitaliy Fedoriv
62	 */
63	
64	@RestController
65	@CrossOrigin(exposedHeaders = "errors, content-type")
66	@RequestMapping("/api")
67	public class OwnerRestControllerV1 implements OwnersApi {
68	
69	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
70	
71	    private final ClinicService clinicService;
72	
73	    private final OwnerMapper ownerMapper;
74	
75	    private final PetMapper petMapper;
76	
77	    private final VisitMapper visitMapper;
78	
79	    public OwnerRestControllerV1(ClinicService clinicService,
80	                                 OwnerMapper ownerMapper,
81	                                 PetMapper petMapper,
82	                                 VisitMapper visitMapper) {
83	        this.clinicService = clinicService;
84	        this.ownerMapper = ownerMapper;
85	        this.petMapper = petMapper;
86	        this.visitMapper = visitMapper;
87	    }
88	
89	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
90	    @Override
91	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
92	        Collection<Owner> owners;
93	        if (lastName != null) {
94	            owners = this.clinicService.findOwnerByLastName(lastName);
95	        } else {
96	            owners = this.clinicService.findAllOwners();
97	        }
98	        if (owners.isEmpty()) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        boolean bulkSignupWarning = isBulkSignupWarning();
102	        List<OwnerDto> ownerDtos = ownerMapper.toOwnerDtoCollection(owners);
103	        ownerDtos.forEach(ownerDto -> ownerDto.setBulkSignupWarning(bulkSignupWarning));
104	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
110	        Owner owner = this.clinicService.findOwnerById(ownerId);
111	        if (owner == null) {
112	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
113	        }
114	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
115	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
116	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
117	    }
118	
119	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
120	    @Override
121	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
122	        String address = normalizeAddress(ownerFieldsDto.getAddress());
123	        List<String> missingFields = new ArrayList<>();
124	        if (isBlank(ownerFieldsDto.getFirstName())) {
125	            missingFields.add("firstName");
126	        }
127	        if (isBlank(ownerFieldsDto.getLastName())) {
128	            missingFields.add("lastName");
129	        }
130	        if (isBlank(address)) {
131	            missingFields.add("address");
132	        }
133	        if (isBlank(ownerFieldsDto.getCity())) {
134	            missingFields.add("city");
135	        }
136	        if (isBlank(ownerFieldsDto.getTelephone())) {
137	            missingFields.add("telephone");
138	        }
139	        if (!missingFields.isEmpty()) {
140	            throw new MissingOwnerFieldsException(missingFields);
141	        }
142	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
143	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
144	        HttpHeaders headers = new HttpHeaders();
145	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
146	        owner.setAddress(address);
147	        owner.setTelephone(telephone);
148	        validateEmailDomain(owner.getEmail());
149	        validatePostcode(owner.getPostcode(), owner.getRegion());
150	        // The household is keyed deterministically on (lastName, postcode): every owner receives the
151	        // same stable householdId as anyone sharing its normalized last name and postcode, without any
152	        // explicit link. This computed value drives duplicate detection and the household size.
153	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
154	        // A second owner joining an existing household (same computed householdId) is rejected as a
155	        // household duplicate. Declaring 'sharesHousehold' only bypasses this block — it no longer
156	        // creates the link, since the link is now implicit in the computed householdId.
157	        if (!sharesHousehold && isHouseholdInUse(owner)) {
158	            throw new DuplicateIdentityException(owner.getIdentityKey());
159	        }
160	        // Remaining duplicate detection is consolidated into the single derived identity key: a create
161	        // is rejected when the new owner's whole identity key equals an existing owner's.
162	        if (isIdentityKeyInUse(owner.getIdentityKey())) {
163	            throw new DuplicateIdentityException(owner.getIdentityKey());
164	        }
165	        if (isCityAtCapacity(owner.getCity())) {
166	            throw new CityAtCapacityException(owner.getCity());
167	        }
168	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(LocalDate.now())) {
169	            throw new FutureRegistrationDateException(owner.getRegistrationDate());
170	        }
171	        LocalDate effectiveDate = owner.getRegistrationDate() != null
172	            ? owner.getRegistrationDate() : LocalDate.now();
173	        LocalDate registrationDate = toBusinessDay(effectiveDate);
174	        if (isDailyRegistrationLimitReached(registrationDate)) {
175	            throw new DailyRegistrationLimitException(registrationDate);
176	        }
177	        owner.setRegistrationDate(registrationDate);
178	        owner.setCustomerCode(customerCodeFor(owner));
179	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
180	        owner.setHouseholdSize(householdSizeAfterCreate(owner.getHouseholdId()));
181	        // A declared household member (one that set 'sharesHousehold' to join an existing household) is
182	        // not a suspected duplicate; otherwise fall back to the soft last-name + postcode match.
183	        Integer possibleDuplicateOf = sharesHousehold ? null : possibleDuplicateOf(owner);
184	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
185	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
186	        this.clinicService.saveOwner(owner);
187	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
188	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
189	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
190	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
191	        headers.setLocation(UriComponentsBuilder.newInstance()
192	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
193	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
194	    }
195	
196	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
197	    @Override
198	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
199	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
200	        if (currentOwner == null) {
201	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
202	        }
203	        currentOwner.setAddress(ownerFieldsDto.getAddress());
204	        currentOwner.setCity(ownerFieldsDto.getCity());
205	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
206	        currentOwner.setLastName(ownerFieldsDto.getLastName());
207	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
208	        this.clinicService.saveOwner(currentOwner);
209	        OwnerDto ownerDto = ownerMapper.toOwnerDto(currentOwner);
210	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
211	        return new ResponseEntity<>(ownerDto, HttpStatus.NO_CONTENT);
212	    }
213	
214	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
215	    @Transactional
216	    @Override
217	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
218	        Owner owner = this.clinicService.findOwnerById(ownerId);
219	        if (owner == null) {
220	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
221	        }
222	        this.clinicService.deleteOwner(owner);
223	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
224	    }
225	
226	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
227	    @Override
228	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
229	        Owner owner = this.clinicService.findOwnerById(ownerId);
230	        if (owner == null) {
231	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
232	        }
233	        HttpHeaders headers = new HttpHeaders();
234	        Pet pet = petMapper.toPet(petFieldsDto);
235	        owner.setId(ownerId);
236	        pet.setOwner(owner);
237	        pet.getType().setName(null);
238	        this.clinicService.savePet(pet);
239	        PetDto petDto = petMapper.toPetDto(pet);
240	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
241	            .buildAndExpand(pet.getId()).toUri());
242	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
243	    }
244	
245	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
246	    @Override
247	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
248	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
249	        if (currentOwner != null) {
250	            Pet currentPet = this.clinicService.findPetById(petId);
251	            if (currentPet != null) {
252	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
253	                currentPet.setName(petFieldsDto.getName());
254	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
255	                this.clinicService.savePet(currentPet);
256	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
257	            }
258	        }
259	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
260	    }
261	
262	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
263	    @Override
264	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
265	        HttpHeaders headers = new HttpHeaders();
266	        Visit visit = visitMapper.toVisit(visitFieldsDto);
267	        Pet pet = new Pet();
268	        pet.setId(petId);
269	        visit.setPet(pet);
270	        this.clinicService.saveVisit(visit);
271	        VisitDto visitDto = visitMapper.toVisitDto(visit);
272	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
273	            .buildAndExpand(visit.getId()).toUri());
274	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
275	    }
276	
277	
278	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
279	    @Override
280	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
281	        Owner owner = this.clinicService.findOwnerById(ownerId);
282	        if (owner != null) {
283	            Pet pet = owner.getPet(petId);
284	            if (pet != null) {
285	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
286	            }
287	        }
288	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
289	    }
290	
291	    private static boolean isBlank(String value) {
292	        return value == null || value.isBlank();
293	    }
294	
295	    /**
296	     * The set of disposable email domains that owners may not register with. Compared
297	     * case-insensitively against the domain part of the supplied email.
298	     */
299	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
300	        "mailinator.com", "tempmail.com", "guerrillamail.com");
301	
302	    /**
303	     * Rejects an owner whose email domain is on the disposable-domain blocklist
304	     * ({@code mailinator.com}, {@code tempmail.com}, {@code guerrillamail.com}). Email is optional:
305	     * a {@code null} or blank value, or one without an {@code '@'} domain part, is accepted here (the
306	     * {@code @Email} Bean Validation constraint governs format). The domain is compared
307	     * case-insensitively; the stored email is already lower-cased.
308	     *
309	     * @param email the owner's email (may be {@code null})
310	     * @throws DisposableEmailDomainException if the email's domain is on the blocklist
311	     */
312	    private static void validateEmailDomain(String email) {
313	        if (isBlank(email)) {
314	            return;
315	        }
316	        int at = email.lastIndexOf('@');
317	        if (at < 0) {
318	            return;
319	        }
320	        String domain = email.substring(at + 1).trim().toLowerCase(java.util.Locale.ROOT);
321	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
322	            throw new DisposableEmailDomainException(email);
323	        }
324	    }
325	
326	    /**
327	     * The fixed, region-keyed inclusive 4-digit postcode ranges. A region absent from this table
328	     * (locality {@code UNKNOWN}) imposes no range, so any 4-digit postcode is accepted there.
329	     */
330	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
331	        "NSW", new int[] {2000, 2099},
332	        "VIC", new int[] {3000, 3099},
333	        "QLD", new int[] {4000, 4099});
334	
335	    /**
336	     * Validates a supplied {@code postcode} against the owner's city region. Postcode is optional:
337	     * a {@code null} or blank value is accepted (validation only applies WHEN PRESENT). When
338	     * present, the value has already passed the 4-digit format check (Bean Validation on the
339	     * request body); this enforces that it falls within the inclusive range for the city's region
340	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region imposes no range.
341	     *
342	     * @param postcode the supplied postcode (may be {@code null})
343	     * @param region the owner's locality/region derived from its city
344	     * @throws InvalidPostcodeException if the postcode is out of range for the region
345	     */
346	    private static void validatePostcode(String postcode, String region) {
347	        if (isBlank(postcode)) {
348	            return;
349	        }
350	        int[] range = REGION_POSTCODES.get(region);
351	        if (range == null) {
352	            return;
353	        }
354	        int value;
355	        try {
356	            value = Integer.parseInt(postcode);
357	        }
358	        catch (NumberFormatException e) {
359	            throw new InvalidPostcodeException(postcode);
360	        }
361	        if (value < range[0] || value > range[1]) {
362	            throw new InvalidPostcodeException(postcode);
363	        }
364	    }
365	
366	    /**
367	     * Normalizes a street address into the canonical form stored on and returned for a newly
368	     * created owner. A {@code null} value becomes the empty string; otherwise surrounding
369	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space, the
370	     * text is upper-cased, and common street-type abbreviations are expanded on a whole-word
371	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The normalized
372	     * value is what gets persisted, echoed back, and used for every address comparison (household
373	     * duplicate detection and the shared household identifier).
374	     *
375	     * @param rawAddress the address value as supplied by the client
376	     * @return the normalized address (possibly empty, never {@code null})
377	     */
378	    private static String normalizeAddress(String rawAddress) {
379	        if (rawAddress == null) {
380	            return "";
381	        }
382	        String collapsed = rawAddress.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
383	        if (collapsed.isEmpty()) {
384	            return "";
385	        }
386	        String[] tokens = collapsed.split(" ");
387	        StringBuilder sb = new StringBuilder(collapsed.length());
388	        for (int i = 0; i < tokens.length; i++) {
389	            String token = tokens[i];
390	            switch (token) {
391	                case "ST" -> token = "STREET";
392	                case "RD" -> token = "ROAD";
393	                case "AVE" -> token = "AVENUE";
394	                default -> { }
395	            }
396	            if (i > 0) {
397	                sb.append(' ');
398	            }
399	            sb.append(token);
400	        }
401	        return sb.toString();
402	    }
403	
404	    /**
405	     * Builds the customer code assigned to a newly created owner. The code is formatted
406	     * {@code <REGION>-<HASH8>} where {@code REGION} is the region derived from the owner's postcode
407	     * (see {@link Owner#getRegion()}) and {@code HASH8} is the first 8 upper-case hex characters of
408	     * the SHA-256 digest of the owner's normalized (E.164) telephone concatenated with its last
409	     * name (e.g. {@code NSW-1A2B3C4D}). No sequence number is involved, so the code depends only on
410	     * the owner's own region and identity.
411	     *
412	     * @param owner the owner being created, with telephone already normalized and postcode/city set
413	     * @return the customer code to assign
414	     */
415	    private static String customerCodeFor(Owner owner) {
416	        return owner.getRegion() + "-" + telephoneNameHash(owner.getTelephone(), owner.getLastName());
417	    }
418	
419	    /**
420	     * Computes the {@code HASH8} segment of the customer code: the first 8 upper-case hex
421	     * characters of the SHA-256 digest of the normalized (E.164) telephone concatenated with the
422	     * last name.
423	     *
424	     * @param normalizedTelephone the owner's telephone in E.164 form
425	     * @param lastName the owner's last name
426	     * @return the 8-character upper-case hex hash
427	     */
428	    private static String telephoneNameHash(String normalizedTelephone, String lastName) {
429	        String key = (normalizedTelephone == null ? "" : normalizedTelephone)
430	            + (lastName == null ? "" : lastName);
431	        try {
432	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
433	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
434	            StringBuilder sb = new StringBuilder(digest.length * 2);
435	            for (byte b : digest) {
436	                sb.append(String.format("%02x", b));
437	            }
438	            return sb.substring(0, 8).toUpperCase(java.util.Locale.ROOT);
439	        }
440	        catch (java.security.NoSuchAlgorithmException e) {
441	            throw new IllegalStateException("SHA-256 not available", e);
442	        }
443	    }
444	
445	    /**
446	     * Normalizes a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value
447	     * already carrying a leading {@code '+'} keeps its country code; otherwise country code
448	     * {@code +61} is assumed and a single leading {@code '0'} is dropped from the national digits.
449	     * The result must carry a leading {@code '+'} followed by 8 to 15 digits, and the length of
450	     * the national number must match the country code: {@code +61} requires 9 national digits and
451	     * {@code +1} requires 10.
452	     *
453	     * @param rawTelephone the telephone value as supplied by the client
454	     * @return the telephone in E.164 form (e.g. {@code +61412345678})
455	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
456	     */
457	    private static String normalizeTelephone(String rawTelephone) {
458	        if (rawTelephone == null) {
459	            throw new InvalidTelephoneException(rawTelephone);
460	        }
461	        String cleaned = rawTelephone.replaceAll("[\\s\\-()]", "");
462	        String e164;
463	        if (cleaned.startsWith("+")) {
464	            String digits = cleaned.substring(1);
465	            if (!digits.matches("[0-9]+")) {
466	                throw new InvalidTelephoneException(rawTelephone);
467	            }
468	            e164 = "+" + digits;
469	        } else {
470	            if (!cleaned.matches("[0-9]+")) {
471	                throw new InvalidTelephoneException(rawTelephone);
472	            }
473	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
474	            e164 = "+61" + national;
475	        }
476	        int digitCount = e164.length() - 1;
477	        if (digitCount < 8 || digitCount > 15) {
478	            throw new InvalidTelephoneException(rawTelephone);
479	        }
480	        if (e164.startsWith("+61")) {
481	            if (e164.length() - "+61".length() != 9) {
482	                throw new InvalidTelephoneException(rawTelephone);
483	            }
484	        }
485	        else if (e164.startsWith("+1")) {
486	            if (e164.length() - "+1".length() != 10) {
487	                throw new InvalidTelephoneException(rawTelephone);
488	            }
489	        }
490	        return e164;
491	    }
492	
493	    /**
494	     * Determines whether any existing owner already carries the given identity key. The identity key
495	     * ({@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}) is the single value
496	     * all duplicate detection is based on, so two owners collide only when their whole identity keys
497	     * are equal.
498	     *
499	     * @param identityKey the identity key of the owner being created
500	     * @return {@code true} if another owner already has the same identity key
501	     */
502	    private boolean isIdentityKeyInUse(String identityKey) {
503	        return this.clinicService.findAllOwners().stream()
504	            .map(Owner::getIdentityKey)
505	            .anyMatch(identityKey::equals);
506	    }
507	
508	    /**
509	     * Finds an existing owner that the owner being created is a possible (soft) duplicate of: one
510	     * that shares the same last name (compared case-insensitively, whitespace-collapsed) and the
511	     * same postcode but carries a <em>different</em> telephone. Such a create is not rejected as a
512	     * hard duplicate, but is flagged. An owner with no postcode can never be a soft duplicate. When
513	     * several owners match, the earliest (lowest id) is returned so the result is deterministic.
514	     *
515	     * @param owner the owner being created (telephone already normalized, postcode set)
516	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
517	     */
518	    private Integer possibleDuplicateOf(Owner owner) {
519	        if (isBlank(owner.getPostcode())) {
520	            return null;
521	        }
522	        String normalizedLastName = normalizeIdentity(owner.getLastName());
523	        return this.clinicService.findAllOwners().stream()
524	            .filter(existing -> existing.getId() != null
525	                && normalizeIdentity(existing.getLastName()).equals(normalizedLastName)
526	                && owner.getPostcode().equals(existing.getPostcode())
527	                && !java.util.Objects.equals(owner.getTelephone(), existing.getTelephone()))
528	            .map(Owner::getId)
529	            .min(Integer::compareTo)
530	            .orElse(null);
531	    }
532	
533	    /**
534	     * Counts how many existing owners already share the given first name and last name with the
535	     * owner being created. Both names are compared case-insensitively (after trimming and
536	     * collapsing runs of whitespace). The count reflects the state before the new owner is
537	     * persisted, so a first, otherwise-unique owner yields {@code 0}.
538	     *
539	     * @param firstName the first name of the owner being created
540	     * @param lastName the last name of the owner being created
541	     * @return the number of existing owners sharing the same first and last name
542	     */
543	    private int namesakeCount(String firstName, String lastName) {
544	        String normalizedFirstName = normalizeIdentity(firstName);
545	        String normalizedLastName = normalizeIdentity(lastName);
546	        return (int) this.clinicService.findAllOwners().stream()
547	            .filter(existing -> normalizeIdentity(existing.getFirstName()).equals(normalizedFirstName)
548	                && normalizeIdentity(existing.getLastName()).equals(normalizedLastName))
549	            .count();
550	    }
551	
552	    /**
553	     * Counts how many members the owner being created belongs to in its household, including
554	     * itself, as of this create. Members are the owners sharing the given {@code householdId};
555	     * the new owner is not yet persisted, so its own membership is added to the existing count.
556	     * An owner not assigned to a shared household ({@code householdId} is {@code null}) is a
557	     * household of one.
558	     *
559	     * @param householdId the shared household identifier assigned to the owner being created, or
560	     *                    {@code null} if the owner does not share a household
561	     * @return the number of household members after this create (at least 1)
562	     */
563	    private int householdSizeAfterCreate(String householdId) {
564	        if (householdId == null) {
565	            return 1;
566	        }
567	        long existing = this.clinicService.findAllOwners().stream()
568	            .filter(owner -> householdId.equals(owner.getHouseholdId()))
569	            .count();
570	        return (int) existing + 1;
571	    }
572	
573	    /**
574	     * The maximum number of owners permitted in a single city. Once a city already contains this
575	     * many owners it is considered full and no further owners may be created there.
576	     */
577	    private static final int CITY_CAPACITY = 50;
578	
579	    /**
580	     * Determines whether the given city has already reached its capacity, i.e. already contains
581	     * {@value #CITY_CAPACITY} or more existing owners. Cities are compared case-insensitively after
582	     * collapsing runs of whitespace to a single space and trimming.
583	     *
584	     * @param city the city of the owner being created
585	     * @return {@code true} if the city already contains {@value #CITY_CAPACITY} or more owners
586	     */
587	    private boolean isCityAtCapacity(String city) {
588	        String normalizedCity = normalizeIdentity(city);
589	        long count = this.clinicService.findAllOwners().stream()
590	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(normalizedCity))
591	            .count();
592	        return count >= CITY_CAPACITY;
593	    }
594	
595	    /**
596	     * The maximum number of owners that may be created on any single day. Once this many owners
597	     * already carry a {@code registrationDate} of the current day, no further owners may be created
598	     * that day.
599	     */
600	    private static final int DAILY_REGISTRATION_LIMIT = 100;
601	
602	    /**
603	     * Determines whether the daily registration limit has already been reached, i.e. whether
604	     * {@value #DAILY_REGISTRATION_LIMIT} or more existing owners already carry the given date as
605	     * their {@code registrationDate}.
606	     *
607	     * @param date the current day
608	     * @return {@code true} if {@value #DAILY_REGISTRATION_LIMIT} or more owners were already
609	     *         registered on the given date
610	     */
611	    /**
612	     * Rolls a registration date forward onto a business day. A date that already falls on a
613	     * weekday is returned unchanged; a Saturday or Sunday is rolled forward to the following
614	     * Monday. This adjusted date is what gets stored as the {@code registrationDate} and drives
615	     * everything derived from it (the membership number's year segment, the daily create-limit).
616	     *
617	     * @param date the effective registration date (supplied by the client or defaulted to the
618	     *             server's current date)
619	     * @return the same date if it is a weekday, otherwise the following Monday
620	     */
621	    private static LocalDate toBusinessDay(LocalDate date) {
622	        DayOfWeek dayOfWeek = date.getDayOfWeek();
623	        if (dayOfWeek == DayOfWeek.SATURDAY) {
624	            return date.plusDays(2);
625	        }
626	        if (dayOfWeek == DayOfWeek.SUNDAY) {
627	            return date.plusDays(1);
628	        }
629	        return date;
630	    }
631	
632	    private boolean isDailyRegistrationLimitReached(LocalDate date) {
633	        long count = this.clinicService.findAllOwners().stream()
634	            .filter(existing -> date.equals(existing.getRegistrationDate()))
635	            .count();
636	        return count >= DAILY_REGISTRATION_LIMIT;
637	    }
638	
639	    /**
640	     * The number of owners that may be created on a single day before the bulk-signup warning is
641	     * raised. Once <em>more than</em> this many owners already carry the current business day as
642	     * their {@code registrationDate}, responses flag {@code bulkSignupWarning} true.
643	     */
644	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
645	
646	    /**
647	     * Determines whether more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been
648	     * created today, i.e. already carry the current business day as their {@code registrationDate}.
649	     * This shares the daily create-limit's accumulation path (owners counted by registration date).
650	     *
651	     * @return {@code true} if more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners are already
652	     *         registered on today's business day
653	     */
654	    private boolean isBulkSignupWarning() {
655	        LocalDate today = toBusinessDay(LocalDate.now());
656	        long count = this.clinicService.findAllOwners().stream()
657	            .filter(existing -> today.equals(existing.getRegistrationDate()))
658	            .count();
659	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
660	    }
661	
662	    /**
663	     * Determines whether the owner being created joins an existing household, i.e. some other owner
664	     * already carries the same computed {@code householdId} (equivalently, shares its normalized last
665	     * name and postcode). An owner with no postcode is never treated as joining a household, mirroring
666	     * the soft-duplicate rule that an owner with no postcode can never match one.
667	     *
668	     * @param owner the owner being created, with {@code householdId} already computed
669	     * @return {@code true} if another owner already belongs to the same household
670	     */
671	    private boolean isHouseholdInUse(Owner owner) {
672	        if (isBlank(owner.getPostcode())) {
673	            return false;
674	        }
675	        String householdId = owner.getHouseholdId();
676	        return this.clinicService.findAllOwners().stream()
677	            .anyMatch(existing -> existing.getId() != null
678	                && householdId.equals(existing.getHouseholdId()));
679	    }
680	
681	    /**
682	     * Derives the stable household identifier for a given last name and postcode. The value is the
683	     * first 12 upper-case hex characters of the SHA-256 digest of {@code normalizedLastName + '|' +
684	     * postcode}, so it is deterministic across calls and identical for every owner sharing the same
685	     * normalized last name and postcode — they belong to the same household automatically.
686	     *
687	     * @param lastName the last name of the household
688	     * @param postcode the postcode of the household (may be {@code null})
689	     * @return the deterministic household identifier
690	     */
691	    private static String householdIdFor(String lastName, String postcode) {
692	        String key = normalizeIdentity(lastName) + "|" + (postcode == null ? "" : postcode);
693	        try {
694	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
695	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
696	            StringBuilder sb = new StringBuilder(digest.length * 2);
697	            for (byte b : digest) {
698	                sb.append(String.format("%02x", b));
699	            }
700	            return sb.substring(0, 12).toUpperCase(java.util.Locale.ROOT);
701	        }
702	        catch (java.security.NoSuchAlgorithmException e) {
703	            throw new IllegalStateException("SHA-256 not available", e);
704	        }
705	    }
706	
707	    /**
708	     * Normalizes a text field for household-identity comparison: {@code null} becomes the empty
709	     * string, surrounding whitespace is trimmed, internal runs of whitespace are collapsed to a
710	     * single space, and the result is lower-cased.
711	     *
712	     * @param value the raw field value
713	     * @return the normalized value used for case-insensitive, whitespace-insensitive comparison
714	     */
715	    private static String normalizeIdentity(String value) {
716	        if (value == null) {
717	            return "";
718	        }
719	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
720	    }
721	}
